C = dict(id='GL-25', title='Inclusive and Minority-Owned Business Growth', group='Business and Commerce', level=4,
 summary='Help under-served owners grow a business: assess where they stand, open fair routes to customers, finance and mentors, and track real progress.',
 outcomes=['Explain barriers owners face and the ways to remove them respectfully.', 'Assess a business with a simple, strengths-first health check.', 'Analyse supplier, customer and finance routes for fairness and fit.', 'Create a 90-day growth plan with the owner.', 'Evaluate progress with agreed measures, led by the owner.'],
 task='Work with one owner (or a practice case) to produce a health check, a 90-day growth plan and a progress report.',
 cond='An owner who agrees to take part, a spreadsheet, public programme lists, a mentor with business-support experience and a peer circle. About 10 weeks part-time.',
 std='The owner agrees the plan and measures in writing; no private data shared beyond agreed people; at least three realistic routes researched; plan has dated actions; progress measured at day 30 and 60.',
 who='Business advisers, community workers, mentors, small-business owners, students.', req='None.',
 safety='Respect, consent and privacy come first. Do not label people or make assumptions. Give no legal or tax advice beyond your role; refer to a qualified adviser.',
 mods=[
 ('Respect and listening', 'The owner leads; you support.', ['Ask what success means to them.', 'Strengths first: skills, products, customers, community.', 'Avoid assumptions and labels.', 'Agree how information is stored and shared.'], 'An owner says "I want steady orders, not a big shop": the plan aims at repeat orders.', 'Hold a listening session and write the owner\'s goals in their words.', 'Ask the owner to confirm the summary.'),
 ('Health check', 'Know where the business stands.', ['Money in and out; margins; debts.', 'Customers: who, how many, repeat rate.', 'Operations: capacity, quality, suppliers.', 'Skills, tools, records, legal basics.'], 'Monthly sales 1,800; costs 1,350; profit 450 (25%); two clients give 70% of sales, so losing one would hurt badly (concentration risk).', 'Complete the health check.', 'Score each area with evidence.'),
 ('Barriers and routes', 'Barriers are often access, not ability.', ['Common barriers: credit, networks, information, language, procurement rules.', 'Routes: programmes, networks, supplier schemes, mentors.', 'Check eligibility and cost.', 'Prefer fair, transparent routes.'], 'A supplier-diversity scheme lists simple steps: register, document, get invited to quotes.', 'Research five routes with steps and costs.', 'Rank the routes by fit.'),
 ('Customers and markets', 'Growth needs buyers.', ['Who buys now and who else could.', 'Offers and prices that fit.', 'Online and local channels.', 'Reviews and referrals.'], 'Owner sells to neighbours; a local canteen could buy weekly: draft a simple price list.', 'Draft two outreach messages and a price list.', 'Write specific messages.'),
 ('Money and finance', 'Fair finance helps; unfair finance harms.', ['Know the full cost of the money: rate, fees and length of loan.', 'Grants, small loans, savings groups, supplier credit.', 'Avoid pressure and hidden fees.', 'Keep simple records.'], 'A loan of 2,000 at 18% (an estimate; check your market) for a year costs 360 in interest; compare with a grant needing no repayment.', 'Compare three finance options.', 'Show the total cost for each.'),
 ('Skills and tools', 'Small upgrades make big differences.', ['Records, pricing, online listing, safety.', 'Free training and mentors.', 'A simple tool stack.', 'Plan learning time.'], 'Owner learns to price with margin: raises prices 8% and keeps customers.', 'Pick two skills and a learning plan.', 'Plan fits owner\'s time.'),
 ('The 90-day plan', 'A short, dated plan beats a long wish list.', ['Three goals; each with three actions.', 'Owner, helper, date for each.', 'Measures: sales, orders, customers, savings.', 'Review day 30 and 60.'], 'Goal: 5 repeat customers by day 60. Actions: call 10 past buyers; offer a bundle; track orders.', 'Write the plan with the owner.', 'Obtain the owner\'s sign-off.'),
 ('Progress and handover', 'Measure honestly and hand over power.', ['Compare with the health check.', 'Celebrate what worked; adjust what did not.', 'Document what the owner can repeat.', 'Plan next steps and who supports.'], 'Day 60: 4 repeat customers against 5; profit up 5 percentage points; keep going with the bundle.', 'Write the progress report.', 'Report uses numbers and owner quotes.')],
 quiz=[('Who leads the plan?', 'The owner.'), ('Why start with strengths?', 'It builds confidence and shows assets to use.'), ('What is concentration risk?', 'Too much income from few customers.'), ('Name three barriers.', 'Credit, networks, information, language or procurement rules.'), ('How to compare finance?', 'By total cost, fees and terms.'), ('What does a good plan include?', 'Goals, actions, owners, dates and measures.'), ('Why get consent?', 'It protects privacy and trust.'), ('When do you review?', 'At day 30 and day 60.'), ('Should you give legal advice?', 'No; refer to a qualified adviser.'), ('Why document learning?', 'So the owner can repeat it.')],
 rubric=[('Respect and consent', 'Written agreement', 'Owner leads every decision'), ('Health check', 'All areas scored', 'Evidence for each score'), ('Routes', 'Five researched', 'Two started'), ('Plan', 'Dated actions', 'Actions met on time'), ('Progress', 'Measured at 30 and 60', 'Results improved')],
 jobs=[('Small-business adviser', 'Supports owners'), ('Community enterprise officer', 'Connects owners to schemes'), ('Mentor coordinator', 'Matches mentors'), ('Procurement support assistant', 'Helps owners bid')],
 next='Business Coaching Practice; Crowdfunding Platform Practice; Digital Marketing.',
 local='Programmes, definitions and legal protections differ by place: use local schemes and respect local law on equality.',
 evidence='Your evidence: owner goals, health check, route research, finance comparison, 90-day plan and progress report.',
 ladder=[('Basics of enterprise', 'Describe what a small enterprise is and what it needs to survive. Notes: talk to one local owner. Standard: a list of three needs they named.'), ('Awareness', 'Describe barriers small owners face (finance, access to buyers, rules, networks) and which are fixable. Notes: sort ten barriers into fixable and structural. Standard: reasons given for each choice.'), ('Foundation', 'Carry out a business health check on a practice case: sales, costs, records, customers and risks. Notes: use a standard checklist. Standard: five findings ranked by effect.'), ('Practitioner', 'Plan 30 days of action for one practice owner with a budget, a buyer list and a measure. Notes: agree each action with the owner. Standard: every action has an owner, a date and a measure.'), ('Specialist', 'Work with one owner or a practice case to produce a health check, a 90-day growth plan and a progress report. Notes: include access to buyers and finance. Standard: report shows the baseline, the actions done and the change in a chosen measure.'), ('Advanced', 'Lead a support programme for several owners with referral partners, fair selection rules and results reporting. Notes: add an annual fairness review. Standard: selection rules published and results reported for all groups served.'), ('Super expert', 'Set the fair-opportunity method for business growth (access to buyers, finance, mentors) and teach the advisers who use it. Notes: review who was reached and who was missed each year and change the outreach.')])

C['deep'] = dict(mods=[
 ('Arriving with a plan before listening.', 'An owner wants steady orders; a growth plan for a big shop would have wasted months.', 'What did the owner say success looks like?'),
 ('Only listing weaknesses.', 'Strengths list: skilled maker, loyal neighbours, low costs; weaknesses: no records.', 'What are three strengths?'),
 ('Naming barriers as if they were the owner\'s fault.', 'Rephrase "poor credit history" as "limited access to fair credit".', 'Which barrier is about access, not ability?'),
 ('Sending mass messages.', 'Two personal messages to specific buyers bring one order.', 'Whom will you contact first?'),
 ('Taking the first loan offered.', 'Offer A costs 360 interest; a grant needs no repayment; compare before choosing.', 'What is the total cost of each option?'),
 ('Training that is too long.', 'A one-hour lesson on pricing is used the same week.', 'Which skill will be used this week?'),
 ('Plans with ten goals.', 'Three goals, nine actions, each with a date.', 'Which three goals did the owner choose?'),
 ('Taking credit for the result.', 'The report quotes the owner\'s own words on what changed.', 'What did the owner say?')],
 gloss=[('Barrier', 'Something that makes it harder to reach a fair outcome.'), ('Concentration risk', 'Relying on few customers.'), ('Margin', 'Money left after costs.'), ('Procurement', 'How organisations buy goods and services.'), ('Mentor', 'A person who shares experience.'), ('Health check', 'A simple review of a business.')],
 cases=[('The big contract', 'A large buyer offers a contract that needs three times current capacity.', 'What do you advise?', 'List what is needed, test a smaller first order, discuss financing and refer to a finance adviser.'),
        ('The scheme with fees', 'A "support programme" asks for an upfront fee.', 'What do you check?', 'Verify the organisation, ask for written terms and warn the owner about pressure.')])
C['deep']['extra'] = [
 ['Agree meeting times that suit the owner\'s working day.', 'Offer to meet at the workplace or online.'],
 ['Collect three months of sales if the owner agrees.', 'Add a note about what the owner is proud of.'],
 ['Keep a list of trusted networks.', 'Note language needs for forms.'],
 ['Draft messages in the owner\'s voice.', 'Ask for one testimonial.'],
 ['Explain interest in plain words.', 'Never push an owner to borrow.'],
 ['Pair the owner with a peer mentor.', 'Keep a learning log.'],
 ['Review the plan weekly for ten minutes.', 'Celebrate small wins.'],
 ['Ask the owner what support they still need.', 'Agree who to call if stuck.']]

_ex = ["The owner says 'I want steady orders, not a big shop.' The plan aims for 5 repeat customers by day 60 rather than expansion.", 'Monthly sales 1,800, costs 1,350, profit 450 (25%). Two clients give 70% of sales, so the plan adds three new buyers.', 'A supplier-diversity scheme lists simple steps: register, document, get invited to quotes. You list the documents the owner already has.', 'Owner sells to neighbours. A local canteen could buy weekly: draft a short price list and two outreach messages.', 'A loan of 2,000 at 18% for a year costs 360 interest. A grant needs no repayment but takes 4 weeks. The owner chooses with the numbers.', 'The owner learns to price with margin, raises prices by 8% and keeps all customers.', 'Goal: 5 repeat customers by day 60. Actions: call 10 past buyers, offer a bundle, track orders weekly.', 'Day 60: 4 repeat customers against 5; profit up 5 percentage points; plan: keep the bundle and call 10 more.']
_extra = ['Meet the owner in a place they choose.', "Use the owner's words in every document.", 'Note strengths before problems.', 'Ask what help they have already tried.', 'Explain every term in plain language.', 'Check eligibility rules before suggesting a scheme.', 'Never promise funding you do not control.', 'Keep a list of free local mentors.', 'Offer to read forms together.', "Record the owner's decisions, not yours.", 'Share only agreed information with others.', 'Celebrate small wins in writing.', 'Review progress with the owner every two weeks.', 'Ask what support is still needed at the end.', 'Hand over every file and template.', 'Write a short lessons note with the owner.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Begin the first meeting by asking the owner to tell their story in their own words for ten minutes, taking notes and repeating back what you heard before suggesting anything.', 'Agree how you will work together, including how often you meet, what stays private and who makes final decisions, and write this down in a short plain-language note.'], ['Score six areas from 1 to 5, such as sales, cash, records, customers, people and tools, to give the owner a simple picture they can understand at a glance.', 'Take the two lowest scores and ask the owner what changed in the last year, since a recent drop often points to a cause that can be fixed.'], ['List every barrier under three headings (money, knowledge and access) and pair each with a realistic route, such as a local support scheme, a mentor or a shared tool.', 'Ask the owner which barrier hurts most today and start there, because early progress on their biggest worry builds trust.'], ['Help the owner name their ten best customers, what each buys and how often, then count how many arrived through recommendation to see which channels work.', 'Test one new market cheaply, such as a market stall or an online listing for two weeks, and record the number of enquiries and sales it produces.'], ['Draw up a simple monthly cash table showing money in, money out and what is left, using real bank figures from the last three months.', 'Show the owner the true cost of one sale and the smallest price rise that would increase profit, using an actual product from their own sales.'], ['Identify two skill gaps that block growth, such as pricing or online selling, and match each to one short training session or a peer who can demonstrate the skill.', 'Choose one free or low-cost tool, such as a basic spreadsheet or an online booking page, and teach the owner to use it in a single practice session.'], ['Set three goals for the 90 days, each with a number and a date, for example 10 new customers by day 60, and display them where the owner will see them daily.', 'Break each goal into weekly actions of under two hours each, and agree a ten-minute check-in call every Friday to review progress.'], ['At day 90, compare the starting health-check scores with the new ones and show the owner the changes in a simple table so progress is clearly visible.', 'Hand over a one-page summary with next steps, useful contacts and the date of a follow-up call, so the owner can continue without your help.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {"1": "A weaver says 'I want fair pay, not mass sales'; the plan sets a floor price of 18 a scarf and 3 fixed buyers instead of a market stall.", "2": "A tailor's monthly sales are 2,400 and costs 2,000: profit 400 (17%). Rent is half of costs, so the first action is to ask for a rent review.", "3": "A scheme to buy from small firms asks for a tax number, a bank letter and a sample; the owner finds she already has two of the three and starts the third.", "4": "A woman who bakes for her street asks the nearby clinic if staff would pay 3 a day for lunch boxes; she tests with 10 boxes.", "5": "A grant of 1,500 needs a 6-week application and a report; a loan of 1,500 at 12% for a year costs 180 in interest. The owner picks the loan because the shop must restock in 3 weeks.", "6": "A cobbler tracks costs for the first time, finds one repair sells at a 5% margin, and raises its price from 8 to 10; 2 of 30 customers complain and the rest stay.", "7": "Goal: 8 new regular buyers by day 45. Actions: visit 15 shops, leave a sample, follow up after 3 days, record each visit on one sheet.", "8": "Day 45: 6 new regular buyers against 8; average order up from 40 to 52; next step is a second visit to the 9 shops that said maybe."}
C['deep']['mods'] = [(m[0], _dupfix.get(str(i + 1), m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ["You will be able to listen first, agree working terms openly, and support an owner's decisions without taking over their business.", 'You will be able to score six business areas on a simple scale, giving the owner an honest starting picture to measure against.', 'You will be able to separate barriers of money, knowledge and access, and match each with a practical route the owner can actually use.', "You will be able to identify an owner's best customers, test one low-cost new market, and judge whether demand is real.", 'You will be able to build a monthly cash table and cost per sale, helping owners judge fair finance and avoid harmful borrowing.', 'You will be able to match skills gaps to short training or peers, and teach one simple tool that saves the owner time.', "You will be able to write a dated 90-day plan with three numbered goals and weekly actions that fit around a busy owner's week.", 'You will be able to compare day-one and day-ninety scores, then hand over a summary so the owner keeps control after you leave.']
